import numpy as np
L=open('fragA.xyz').read().split('\n')
n=int(L[0]); 
import numpy as np
sym=[];xyz=[]
for l in L[2:2+n]:
    p=l.split(); sym.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz=np.array(xyz)
for i in [0,1,30,31,32,33,34,35]:
    print(i,sym[i],xyz[i])
def d(a,b): return np.linalg.norm(xyz[a]-xyz[b])
print('Au-C',d(0,1),d(0,30),d(30,31),d(31,32),d(32,33),d(33,34),d(34,35))
def ang(a,b,c):
    v1=xyz[a]-xyz[b];v2=xyz[c]-xyz[b]
    return np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2)))
print(ang(1,0,30),ang(0,30,31),ang(30,31,32),ang(31,32,33),ang(32,33,34),ang(33,34,35))
